python3 -I -c "import subprocess,json
def tr(o,d=0):
    if isinstance(o,str): return o[:150]
    if isinstance(o,list): return [tr(x,d+1) for x in o[:14]]
    if isinstance(o,dict): return {k:tr(v,d+1) for k,v in o.items()}
    return o
for f,k in [('benchmark/challenges/library-icon-tests.json','extra-true-answer'),('benchmark/challenges/library-specialty.json','positive-control')]:
    s=subprocess.run(['git','show','27e7495d:'+f],capture_output=True,text=True).stdout
    j=json.loads(s)
    print(f,list(j.keys()) if isinstance(j,dict) else type(j))
    def find(o,p=''):
        if isinstance(o,dict):
            if o.get('name')==k: yield p,o
            for a,v in o.items(): yield from find(v,p+'/'+a)
        elif isinstance(o,list):
            for i,v in enumerate(o): yield from find(v,p+'/'+str(i))
    for p,o in find(j):
        print(p); print(json.dumps(tr(o),indent=1)[:6000])
    print('=====')"

